import pytest

from bedrock_protocol import v1001, v2168, v2225

VERSIONS = [v1001, v2168, v2225]

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.SetHud{Elements: []int32{0, 5, 12}, Visibility: 1}
HUD = bytes.fromhex("03000a1802")

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.SetHud{Elements: []int32{12}, Visibility: 0}
SINGLE_ELEMENT = bytes.fromhex("011800")

GOLDENS = [
    pytest.param(
        v.SetHudPacket(
            hud_element=[v.HudElement.PAPER_DOLL, v.HudElement.HOT_BAR, v.HudElement.ITEM_TEXT],
            hud_visible=v.HudVisibility.RESET,
        ),
        HUD,
        id=f"{v.__name__.rpartition('.')[2]}-three-elements",
    )
    for v in VERSIONS
] + [
    pytest.param(
        v.SetHudPacket(hud_element=[v.HudElement.ITEM_TEXT], hud_visible=v.HudVisibility.HIDE),
        SINGLE_ELEMENT,
        id=f"{v.__name__.rpartition('.')[2]}-zigzagged-element",
    )
    for v in VERSIONS
]


@pytest.mark.parametrize("version", VERSIONS)
def test_set_hud_is_packet_308(version):
    assert version.PACKETS[308] is version.SetHudPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_hud_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_hud_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
